CREATE TABLE customers (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_tokens (hash TEXT PRIMARY KEY, email TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', purpose TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE customer_sessions (hash TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE INDEX session_customer ON customer_sessions(customer_id);
CREATE TABLE customer_addresses (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, label TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE customer_orders (order_id TEXT PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE);
CREATE INDEX customer_order_owner ON customer_orders(customer_id);
CREATE TABLE product_details (product_id TEXT PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE, generation TEXT NOT NULL DEFAULT '', compatibility TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '', edition TEXT NOT NULL DEFAULT '', box_contents TEXT NOT NULL DEFAULT '', warranty TEXT NOT NULL DEFAULT '', denomination TEXT NOT NULL DEFAULT '', redemption TEXT NOT NULL DEFAULT '', delivery_terms TEXT NOT NULL DEFAULT '', sale_mode TEXT NOT NULL DEFAULT 'stock' CHECK(sale_mode IN ('stock','preorder')), release_date TEXT NOT NULL DEFAULT '', deposit_terms TEXT NOT NULL DEFAULT '');
CREATE TABLE store_inquiries (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('contact','preorder')), customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', message TEXT NOT NULL, product_id TEXT REFERENCES products(id) ON DELETE SET NULL, variant_id TEXT REFERENCES product_variants(id) ON DELETE SET NULL, quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity BETWEEN 1 AND 20), status TEXT NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','CONTACTED','CONFIRMED','FULFILLED','CANCELLED')), staff_notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE newsletter_subscribers (email TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','subscribed','unsubscribed')), unsubscribe_hash TEXT NOT NULL UNIQUE, consent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TEXT);
CREATE TABLE promotions (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', image_key TEXT NOT NULL DEFAULT '', href TEXT NOT NULL DEFAULT '/shop', cta TEXT NOT NULL DEFAULT 'Shop now', enabled INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, starts_at TEXT NOT NULL DEFAULT '', ends_at TEXT NOT NULL DEFAULT '');
CREATE TABLE digital_deliveries (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, item_id TEXT NOT NULL UNIQUE REFERENCES order_items(id) ON DELETE CASCADE, ciphertext TEXT NOT NULL, delivered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO site_settings(key,value) VALUES ('payment_policy',''),('warranty_policy',''),('authenticity_policy',''),('delivery_estimates',''),('newsletter_enabled','false'),('contact_enabled','false'),('preorders_enabled','false');
